const stats = $('Fetch Full Stats').item.json;
const weeklyReport = $('AI Weekly Report').item.json;
const lossAnalysis = $('AI Loss Analysis').item.json;
const s = stats.summary || {};

// Week date range
const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(now.getDate() - 7);
const weekLabel = `${weekStart.toLocaleDateString('en-IN', {day:'numeric',month:'short'})} – ${now.toLocaleDateString('en-IN', {day:'numeric',month:'short',year:'numeric'})}`;

// Week slice from timeline
const timeline = stats.timeline || [];
const weekTimeline = timeline.slice(-7);
const weekPurchased = weekTimeline.reduce((s,d) => s+(d.purchased||0), 0);
const weekDispatched = weekTimeline.reduce((s,d) => s+(d.dispatched||0), 0);
const weekLoss = weekTimeline.reduce((s,d) => s+(d.loss||0), 0);
const weekLossRate = weekPurchased > 0 ? ((weekLoss/weekPurchased)*100).toFixed(1) : '0.0';

const lossColor = parseFloat(weekLossRate) > 20 ? '#F87171' : parseFloat(weekLossRate) > 10 ? '#FB923C' : '#4ADE80';
const trend = weekDispatched > weekPurchased*0.8 ? '📈 Strong' : weekDispatched > weekPurchased*0.5 ? '📊 Moderate' : '📉 Weak';

// Bar chart rows for timeline
const maxVal = Math.max(...weekTimeline.map(d => Math.max(d.purchased||0, d.dispatched||0, 1)));
const timelineRows = weekTimeline.map(d => {
  const pPct = Math.round(((d.purchased||0)/maxVal)*100);
  const dPct = Math.round(((d.dispatched||0)/maxVal)*100);
  const label = d.date ? d.date.slice(5) : '';
  return `<tr>
    <td style='padding:6px 8px;font-size:11px;color:#8A7E6E;white-space:nowrap'>${label}</td>
    <td style='padding:6px 4px'><div style='background:#F59E0B;height:10px;width:${pPct}%;min-width:2px;border-radius:2px'></div></td>
    <td style='padding:6px 4px'><div style='background:#4ADE80;height:10px;width:${dPct}%;min-width:2px;border-radius:2px'></div></td>
    <td style='padding:6px 8px;font-size:11px;color:#F59E0B;white-space:nowrap'>${(d.purchased||0).toLocaleString()} kg</td>
    <td style='padding:6px 8px;font-size:11px;color:#4ADE80;white-space:nowrap'>${(d.dispatched||0).toLocaleString()} kg</td>
  </tr>`;
}).join('');

const materialRows = (stats.by_material||[]).map(m => {
  const pct = s.total_purchased > 0 ? ((m.quantity/s.total_purchased)*100).toFixed(1) : 0;
  return `<tr>
    <td style='padding:10px 8px;color:#E8DCC8;font-size:13px'>${m.label}</td>
    <td style='padding:10px 8px'>
      <div style='background:#2A2A2A;height:8px;border-radius:4px;overflow:hidden'>
        <div style='background:#F59E0B;height:8px;width:${pct}%;border-radius:4px'></div>
      </div>
    </td>
    <td style='padding:10px 8px;color:#F59E0B;font-size:13px;font-weight:700;text-align:right'>${(m.quantity||0).toLocaleString()} kg</td>
    <td style='padding:10px 8px;color:#8A7E6E;font-size:11px;text-align:right'>${pct}%</td>
  </tr>`;
}).join('');

const html = `<!DOCTYPE html><html><head><meta charset='utf-8'></head>
<body style='margin:0;padding:0;background:#0D0D0D;font-family:monospace'>
<div style='max-width:680px;margin:0 auto'>

  <!-- Header -->
  <div style='background:#141414;border-bottom:3px solid #F59E0B;padding:40px 32px;text-align:center'>
    <div style='font-size:30px;font-weight:800;color:#F59E0B;letter-spacing:-1px'>♻ TraceFlow</div>
    <div style='font-size:13px;color:#8A7E6E;text-transform:uppercase;letter-spacing:4px;margin-top:6px'>Weekly Operations Report</div>
    <div style='font-size:12px;color:#3A3328;margin-top:4px'>${weekLabel}</div>
  </div>

  <!-- Week KPIs -->
  <div style='display:grid;background:#2A2A2A;gap:1px'>
    <table width='100%' style='border-collapse:collapse;background:#2A2A2A'><tr>
      <td style='background:#141414;padding:24px;text-align:center'>
        <div style='font-size:10px;color:#8A7E6E;text-transform:uppercase;letter-spacing:2px'>This Week — Purchased</div>
        <div style='font-size:36px;font-weight:700;color:#F59E0B;margin:8px 0'>${weekPurchased.toLocaleString()}</div>
        <div style='font-size:11px;color:#8A7E6E'>kilograms</div>
      </td>
      <td style='background:#141414;padding:24px;text-align:center'>
        <div style='font-size:10px;color:#8A7E6E;text-transform:uppercase;letter-spacing:2px'>This Week — Dispatched</div>
        <div style='font-size:36px;font-weight:700;color:#4ADE80;margin:8px 0'>${weekDispatched.toLocaleString()}</div>
        <div style='font-size:11px;color:#8A7E6E'>${trend} dispatch</div>
      </td>
      <td style='background:#141414;padding:24px;text-align:center'>
        <div style='font-size:10px;color:#8A7E6E;text-transform:uppercase;letter-spacing:2px'>This Week — Loss</div>
        <div style='font-size:36px;font-weight:700;color:${lossColor};margin:8px 0'>${weekLossRate}%</div>
        <div style='font-size:11px;color:#8A7E6E'>${weekLoss.toLocaleString()} kg lost</div>
      </td>
    </tr></table>
  </div>

  <!-- AI Report -->
  <div style='padding:28px 32px'>
    <div style='font-size:11px;color:#F59E0B;text-transform:uppercase;letter-spacing:3px;border-bottom:1px solid #2A2A2A;padding-bottom:8px;margin-bottom:16px'>✦ Weekly AI Analysis</div>
    <div style='background:#141414;border-left:3px solid #F59E0B;padding:20px;color:#E8DCC8;font-size:14px;line-height:1.8;border-radius:0 8px 8px 0'>${weeklyReport.reply || 'Report unavailable.'}</div>
  </div>

  <!-- Loss Analysis -->
  <div style='padding:0 32px 28px'>
    <div style='font-size:11px;color:#FB923C;text-transform:uppercase;letter-spacing:3px;border-bottom:1px solid #2A2A2A;padding-bottom:8px;margin-bottom:16px'>⚠ Loss Analysis</div>
    <div style='background:#141414;border-left:3px solid #FB923C;padding:20px;color:#E8DCC8;font-size:14px;line-height:1.8;border-radius:0 8px 8px 0'>${lossAnalysis.reply || 'Loss data unavailable.'}</div>
  </div>

  <!-- 7-Day Chart -->
  <div style='padding:0 32px 28px'>
    <div style='font-size:11px;color:#F59E0B;text-transform:uppercase;letter-spacing:3px;border-bottom:1px solid #2A2A2A;padding-bottom:8px;margin-bottom:16px'>7-Day Flow Chart</div>
    <div style='background:#141414;border-radius:8px;padding:16px'>
      <table width='100%' style='border-collapse:collapse'>
        <tr>
          <th style='font-size:10px;color:#8A7E6E;text-align:left;padding:4px 8px'>Date</th>
          <th style='font-size:10px;color:#F59E0B;text-align:left;padding:4px 8px' colspan='2'>Purchased</th>
          <th style='font-size:10px;color:#4ADE80;text-align:left;padding:4px 8px' colspan='2'>Dispatched</th>
        </tr>
        ${timelineRows}
      </table>
      <div style='margin-top:12px;font-size:10px;color:#8A7E6E'>🟡 Purchased &nbsp;&nbsp; 🟢 Dispatched</div>
    </div>
  </div>

  <!-- Material Breakdown -->
  <div style='padding:0 32px 28px'>
    <div style='font-size:11px;color:#F59E0B;text-transform:uppercase;letter-spacing:3px;border-bottom:1px solid #2A2A2A;padding-bottom:8px;margin-bottom:8px'>Material Breakdown (All Time)</div>
    <table width='100%' style='border-collapse:collapse;background:#141414;border-radius:8px'>
      <tr style='background:#1C1C1C'>
        <th style='padding:10px 8px;font-size:10px;color:#8A7E6E;text-align:left;text-transform:uppercase;letter-spacing:1px'>Material</th>
        <th style='padding:10px 8px;font-size:10px;color:#8A7E6E;text-align:left;text-transform:uppercase;letter-spacing:1px'>Share</th>
        <th style='padding:10px 8px;font-size:10px;color:#8A7E6E;text-align:right;text-transform:uppercase;letter-spacing:1px'>Volume</th>
        <th style='padding:10px 8px;font-size:10px;color:#8A7E6E;text-align:right;text-transform:uppercase;letter-spacing:1px'>%</th>
      </tr>
      ${materialRows}
    </table>
  </div>

  <!-- Footer -->
  <div style='background:#141414;border-top:1px solid #2A2A2A;padding:20px 32px;text-align:center'>
    <div style='font-size:11px;color:#8A7E6E'>TraceFlow Weekly Report · Auto-generated ${new Date().toISOString()}</div>
  </div>

</div></body></html>`;

const subject = `TraceFlow Weekly Report — ${weekLabel} | Dispatched: ${weekDispatched.toLocaleString()} kg | Loss: ${weekLossRate}%`;

return [{ json: { html, subject, weekPurchased, weekDispatched, weekLoss, weekLossRate } }];
